    {"claim": "By requiring companies to provide standardized 'safety labels' that detail addictive design features, we empower families to make informed choices.", "targets": []}
  ],
  "key_assumptions": [
    {"assumption": "The state is inherently prone to using regulatory power for ideological agenda-setting rather than purely protective health outcomes.", "if_wrong": "If the state were a neutral, non-ideological actor, then state-mandated developmental infrastructure would be a safe and efficient way to protect minors."}
